const first = $input.first().json;
const raw = first.stdout ?? first.data ?? '';
let records = [];
try { records = JSON.parse(raw); } catch (e) {
  return [{ json: { message: `⚠️ Backup verification could not parse backup_check.sh output: ${e.message}\nraw: ${String(raw).slice(0,500)}` } }];
}
const failed = records.filter(r => r.status !== 'ok');
if (failed.length === 0) return [];
const lines = failed.map(r => {
  if (r.status === 'missing') return `🔴 ${r.service} — no backup file found at all`;
  const bits = [];
  if (!r.integrityOk) bits.push('failed integrity check');
  if (r.stale) bits.push(`stale (${r.ageDays}d old, threshold ${r.staleThresholdDays}d)`);
  return `🟠 ${r.service} — ${bits.join(', ')} (${r.file})`;
});
return [{ json: { message: `**Backup Verification — failures found**\n${lines.join('\n')}` } }];
